package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	if dsn == "" {
		dsn = "postgres://appuser:apppass@localhost:5432/inventory?sslmode=disable"
	}
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Build base query
	query := "SELECT id, name, price, sku FROM products WHERE active = true"

	if category != "" {
		// Category filter - parameterized
		query += fmt.Sprintf(" AND category = '%s'", category)
	}

	if minPrice != "" {
		query += " AND price >= " + minPrice
	}

	// Sort handling with apparent whitelist
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if sortBy != "" {
		if allowedSorts[strings.ToLower(sortBy)] {
			query += " ORDER BY " + sortBy
		} else {
			query += " ORDER BY name"
		}
	}

	query += " LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// bulkUpdate handles inventory updates via POST
func bulkUpdate(w http.ResponseWriter, r *http.Request) {
	apiKey := r.Header.Get("X-Internal-Key")
	expectedKey := os.Getenv("INTERNAL_API_KEY")
	if apiKey == "" || apiKey != expectedKey {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	var updates []struct {
		SKU   string  `json:"sku"`
		Price float64 `json:"price"`
		Qty   int     `json:"qty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&updates); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	for _, u := range updates {
		_, err := db.Exec("UPDATE products SET price=$1, quantity=$2 WHERE sku=$3",
			u.Price, u.Qty, u.SKU)
		if err != nil {
			log.Printf("Update failed for %s: %v", u.SKU, err)
		}
	}
	w.WriteHeader(http.StatusNoContent)
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/bulk-update", bulkUpdate)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
